def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, deque

    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    seen = set()
    out = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                        grid[ny][nx] == bg and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        q.append((ny, nx))

            # Recolor background regions except those reaching the bottom or right edge.
            if not any(y == h - 1 or x == w - 1 for y, x in comp):
                for y, x in comp:
                    out[y][x] = 3
    return out
